// The console's pure logic: how observed facts fold into session state.
//
// No `$`, no engine, no I/O here. Every function takes a ConsoleState and
// returns the next one; the hooks in register.tsx do the observing and the
// engine does the keeping. The meaning of every field comes from the one status
// model (status-model.mjs), never from this file.

import {
  emptyStatus,
  markRead,
  reduceStatus,
  sanitizeDisplay,
  withReading,
} from './status-model.mjs'
import type { EntropyReading, SkillHeavenStatus, SkillReceipt, SummonEvent } from './status-model.mjs'
import type { ConsoleAgent, ConsoleBand, ConsoleEntryData, ConsoleSection, ConsoleStateData } from '../types'

export type { ConsoleAgent, ConsoleBand, ConsoleSection }

/** The state contract (types/index.d.ts) keeps `status` and `event` opaque because
 * the engine wants that file self-contained; these are their real types, and
 * `fromData` / `toData` are the only place the two meet. */
export type ConsoleEntry = Omit<ConsoleEntryData, 'event'> & { event: SummonEvent }
export type ConsoleState = Omit<ConsoleStateData, 'status' | 'entries'> & {
  status: SkillHeavenStatus
  entries: ConsoleEntry[]
}
export const fromData = (data: ConsoleStateData): ConsoleState => data as unknown as ConsoleState
export const toData = (state: ConsoleState): ConsoleStateData => state as unknown as ConsoleStateData

export const MAX_ENTRIES = 50
/** Agents kept in Flow, newest last. */
export const MAX_AGENTS = 100
/** Skills stored per entry; the rest are counted in `omitted`. */
export const MAX_SKILLS_PER_ENTRY = 20

/** The summon tool, however the session spells it:
 * `mcp__plugin_skill-heaven_skill-summon__summon` (marketplace install) or
 * `mcp__skill-summon__summon` (launcher). Anchored at both ends: a server that
 * merely ends in "skill-summon" (`mcp__evil-skill-summon__summon`) is not it.
 * register.tsx spells the same pattern as a literal in its tool.call matcher;
 * a repository test holds the two equal. */
export const SUMMON_TOOL = /^mcp__(?:plugin_skill-heaven_)?skill-summon__summon$/
export const MARKETPLACE_SUMMON_TOOL = 'mcp__plugin_skill-heaven_skill-summon__summon'
export const LAUNCHER_SUMMON_TOOL = 'mcp__skill-summon__summon'

/** The console watches the whole session, so zero is honest at the start. */
export function initialState(): ConsoleState {
  return {
    status: {
      ...emptyStatus(),
      reading: { kind: 'native', source: 'no-launcher' },
      skills: 0,
      summons: 0,
      summonTool: 'unknown',
    },
    entries: [],
    band: null,
    agents: [],
    agentIdsSeen: false,
    section: 'session',
    openEntry: null,
    selectedFrom: null,
    hostVersion: null,
    seq: 0,
  }
}

/* ------------------------------------------------------------------------- *
 * Reading a tool result
 * ------------------------------------------------------------------------- */

type Rec = Record<string, unknown>
const isRec = (v: unknown): v is Rec => typeof v === 'object' && v !== null && !Array.isArray(v)

const looksLikeSummon = (v: unknown): v is Rec =>
  isRec(v) && ('summoned' in v || 'previewed' in v || 'noMatch' in v)

/**
 * The summon tool's `structuredContent`, wherever the host put it.
 *
 * Observed on Claude Code 2.1.294 (PR #187, a `tool.call` hook and the console's
 * own `$.tool.call`): an MCP tool's result is `{ ref, result, text }` where
 * `result` is a STRING — the server's JSON text block — and `text` is the same
 * text; `structuredContent` appears nowhere. The object forms stay as
 * fallbacks for a host that does pass it through.
 */
export function structuredOf(r: unknown): unknown {
  if (!isRec(r)) return undefined
  const result = r.result
  if (isRec(result)) {
    if (looksLikeSummon(result.structuredContent)) return result.structuredContent
    if (looksLikeSummon(result)) return result
  }
  if (looksLikeSummon(r.structuredContent)) return r.structuredContent
  const texts: string[] = []
  if (typeof r.text === 'string') texts.push(r.text)
  if (typeof result === 'string' && result !== r.text) texts.push(result)
  if (isRec(result) && Array.isArray(result.content)) {
    for (const block of result.content) {
      if (isRec(block) && typeof block.text === 'string') texts.push(block.text)
    }
  }
  for (const text of texts) {
    try {
      const parsed: unknown = JSON.parse(text)
      if (looksLikeSummon(parsed)) return parsed
    } catch {
      // not all JSON: the object may be followed by resource-link text
    }
    const embedded = firstJsonObject(text)
    if (looksLikeSummon(embedded)) return embedded
  }
  return undefined
}

/** The first balanced `{ ... }` in `text` that parses as JSON. Strings are skipped
 * over so a brace inside one does not unbalance the scan. */
export function firstJsonObject(text: string): unknown {
  for (let start = text.indexOf('{'); start !== -1; start = text.indexOf('{', start + 1)) {
    let depth = 0
    let inString = false
    for (let i = start; i < text.length; i++) {
      const ch = text[i]
      if (inString) {
        if (ch === '\\') i++
        else if (ch === '"') inString = false
      } else if (ch === '"') inString = true
      else if (ch === '{') depth++
      else if (ch === '}' && --depth === 0) {
        try {
          return JSON.parse(text.slice(start, i + 1))
        } catch {
          break // not JSON from here; try the next opening brace
        }
      }
    }
  }
  return undefined
}

/* ------------------------------------------------------------------------- *
 * Agents (Flow)
 * ------------------------------------------------------------------------- */

const shortId = (id: string) => sanitizeDisplay(id, 12)

/** A label for an agent the host named only by id. */
export function agentLabelFor(state: ConsoleState, id: string | null | undefined): string {
  if (id === null || id === undefined) return 'main agent'
  const row = state.agents.find((a) => a.id === id)
  return row ? row.label : `agent ${shortId(id)}`
}

/** subagent type + the call's own description, both sanitized (they are the model's words). */
export function agentCallLabel(subagentType: unknown, description: unknown): string {
  const type = typeof subagentType === 'string' && subagentType ? sanitizeDisplay(subagentType, 24) : 'agent'
  const desc = typeof description === 'string' && description ? sanitizeDisplay(description, 48) : ''
  return desc ? `${type}  "${desc}"` : type
}

/** The host reported an agent id on a call: remember that it did, and the agent. */
export function noteAgentId(state: ConsoleState, id: string): ConsoleState {
  if (state.agents.some((a) => a.id === id)) return state.agentIdsSeen ? state : { ...state, agentIdsSeen: true }
  // An Agent call that has not been given its id yet and is still open: leave it for finishAgentCall.
  const agents: ConsoleAgent[] = [
    ...state.agents,
    { key: id, id, label: `agent ${shortId(id)}`, state: 'running' as const },
  ].slice(-MAX_AGENTS)
  return { ...state, agentIdsSeen: true, agents }
}

export function startAgentCall(state: ConsoleState, key: string, label: string, background: boolean): ConsoleState {
  if (state.agents.some((a) => a.key === key)) return state
  return {
    ...state,
    agents: [...state.agents, { key, id: null, label, state: background ? ('started' as const) : ('running' as const) }].slice(-MAX_AGENTS),
  }
}

/** The Agent call was refused or failed: it started nothing, so it leaves no row. */
export function dropAgentCall(state: ConsoleState, key: string): ConsoleState {
  return state.agents.some((a) => a.key === key) ? { ...state, agents: state.agents.filter((a) => a.key !== key) } : state
}

/** The Agent call's `next` resolved. The result may carry the new agent's id. */
export function finishAgentCall(state: ConsoleState, key: string, agentId: string | null, background: boolean): ConsoleState {
  // The agent may have shown up by id (a stub row) before its call resolved: keep one, labelled row.
  const agents = state.agents
    .filter((a) => agentId === null || a.key !== agentId || a.key === key)
    .map((a) =>
      a.key === key ? { ...a, id: agentId ?? a.id, state: background ? ('started' as const) : ('returned' as const) } : a,
    )
  return { ...state, agents, agentIdsSeen: state.agentIdsSeen || agentId !== null }
}

/** The agent's own loop finished (its `turn.complete`). */
export function agentReturned(state: ConsoleState, agentId: string): ConsoleState {
  if (!state.agents.some((a) => a.id === agentId && a.state !== 'returned')) return state
  return { ...state, agents: state.agents.map((a) => (a.id === agentId ? { ...a, state: 'returned' as const } : a)) }
}

/* ------------------------------------------------------------------------- *
 * Events
 * ------------------------------------------------------------------------- */

/** Keep a bounded number of skills per entry; the rest are counted, not stored. */
function bounded(event: SummonEvent): { event: SummonEvent; omitted: number } {
  if ((event.kind === 'summoned' || event.kind === 'previewed') && event.skills.length > MAX_SKILLS_PER_ENTRY) {
    return { event: { ...event, skills: event.skills.slice(0, MAX_SKILLS_PER_ENTRY) }, omitted: event.skills.length - MAX_SKILLS_PER_ENTRY }
  }
  return { event, omitted: 0 }
}

/**
 * Fold one observed summon-tool call into state. `reached` is false when the
 * call never got an answer from the tool (a /lens preview that was aborted or
 * refused): that says nothing about whether the tool is connected.
 */
export function recordEvent(
  state: ConsoleState,
  event: SummonEvent,
  agent: string | null,
  via: ConsoleEntry['via'],
  reached = true,
): ConsoleState {
  const id = state.seq + 1
  const kept = bounded(event)
  const entry: ConsoleEntry = {
    id,
    event: kept.event,
    omitted: kept.omitted,
    agent,
    via,
    readBy: 'skills' in kept.event ? kept.event.skills.map(() => null) : [],
  }
  const entries = [...state.entries, entry].slice(-MAX_ENTRIES)
  const withAgent = agent !== null ? noteAgentId(state, agent) : state
  const status = reduceStatus(state.status, event)
  return {
    ...withAgent,
    status: reached ? { ...status, summonTool: 'connected' } : status,
    entries,
    band: { kind: 'event', id },
    seq: id,
  }
}

/** A Read of a path: any summoned skill whose materialized SKILL.md it is, is now in context. */
export function recordRead(state: ConsoleState, path: string, reader: string): ConsoleState {
  let changed = false
  const entries = state.entries.map((entry) => {
    const next = markRead(entry.event, path)
    if (next === entry.event) return entry
    changed = true
    const readBy = [...entry.readBy]
    if (next.kind === 'summoned' && entry.event.kind === 'summoned') {
      const before = entry.event.skills
      next.skills.forEach((skill, i) => {
        if (skill.stage === 'in-context' && before[i]?.stage !== 'in-context') readBy[i] = reader
      })
    }
    return { ...entry, event: next, readBy }
  })
  return changed ? { ...state, entries } : state
}

export function recordSelection(state: ConsoleState, reading: EntropyReading, typed: string): ConsoleState {
  return { ...withStatusReading(state, reading), selectedFrom: sanitizeDisplay(typed, 40) }
}

function withStatusReading(state: ConsoleState, reading: EntropyReading): ConsoleState {
  return { ...state, status: withReading(state.status, reading) }
}

export function entryById(state: ConsoleState, id: number): ConsoleEntry | undefined {
  return state.entries.find((e) => e.id === id)
}

/* ------------------------------------------------------------------------- *
 * What the person sees about an entry
 * ------------------------------------------------------------------------- */

export interface StageText {
  text: string
  /** True when the claim is derived by this UI (no read seen), not observed. */
  inferred: boolean
}

/** §2.3 — the card versus context distinction, in the console's own words. */
export function stageText(entry: ConsoleEntry): StageText {
  const event = entry.event
  if (event.kind !== 'summoned') return { text: 'nothing materialized', inferred: false }
  const skills = event.skills
  const inContext = skills.filter((s) => s.stage === 'in-context')
  if (skills.length > 0 && inContext.length === skills.length) {
    const readers = Array.from(new Set(skills.map((_, i) => entry.readBy[i] ?? 'an agent')))
    return { text: `in context · body read by ${readers.join(', ')}`, inferred: false }
  }
  if (inContext.length > 0) {
    return { text: `${inContext.length} of ${skills.length} in context · the rest: card returned · body not read`, inferred: false }
  }
  return { text: 'card returned · body not read', inferred: true }
}

/** A name that may be put in the prompt after the summon command: plain words
 * only. Tree skills carry display names with spaces ("Frontend Code Review",
 * observed live), which are safe and are what the engine matches exactly. */
export function summonableName(skill: SkillReceipt | undefined): string | null {
  if (!skill) return null
  const name = sanitizeDisplay(skill.name, 64)
  return /^[A-Za-z0-9][A-Za-z0-9._:/-]*(?: [A-Za-z0-9._:/-]+)*$/.test(name) ? name : null
}

/** The five Skill Heaven surfaces a pre-fill may name. */
const SURFACE_COMMANDS = new Set(['summon', 'skill-zero', 'skill-heaven', 'skill-hell', 'skill-ultra'])

/**
 * The spelling of a Skill Heaven command that this session accepts, for a
 * pre-fill. Observed on Claude Code 2.1.294: a bare `/skill-zero` (or
 * `/skill-hell high`) resolves to the plugin's portable skill, which is
 * `user-invocable: false`, and the host refuses it ("can only be invoked by
 * Claude"); the plugin-qualified `/skill-heaven:skill-zero`, the spelling the
 * `/` menu shows, reaches the command. Always the one plugin's own name: a
 * look-alike `other:summon` is never filled.
 */
export function qualifyCommand(text: string): string {
  const m = /^\/([a-z-]+)(\s.*)?$/.exec(text)
  if (!m || !SURFACE_COMMANDS.has(m[1]!)) return text
  return `/skill-heaven:${m[1]!}${m[2] ?? ''}`
}

/** §5.2: Summon is offered for a /lens preview with exactly one candidate. */
export function summonSuggestion(entry: ConsoleEntry): string | null {
  const event = entry.event
  if (event.kind !== 'previewed' || event.skills.length !== 1) return null
  return summonableName(event.skills[0])
}

export function timeLabel(at: string | null): string {
  if (!at) return ''
  const d = new Date(at)
  if (Number.isNaN(d.getTime())) return ''
  const two = (n: number) => String(n).padStart(2, '0')
  return `${two(d.getHours())}:${two(d.getMinutes())}:${two(d.getSeconds())}`
}

files.hooks/views.tsx:
// Drawing: the Lens band and the /heaven pane, as trees of the surface's own
// elements. Pure functions of state — no `$`, no writes. A press is handed back
// to the hook that drew the tree through the `actions` objects below, so this
// file cannot change anything by itself.
//
// Every string that came from the network or from a model (skill names, queries,
// sources, reasons, agent labels) reaches the screen through the status model's
// sanitizer or its renderers. Colour is never the only carrier of meaning: each
// state keeps its glyph and its word.

import type { Elements, RenderElement } from 'claude-code'

import {
  CHIP_LABEL,
  HARNESS_PATHS,
  ROLE_COLORS,
  eventLines,
  formatMs,
  formatScore,
  noticeLines,
  readingRung,
  readingToken,
  renderStatusSegments,
  sanitizeDisplay,
} from './status-model.mjs'
import type { EvidenceClass, Role, Segment, SkillReceipt } from './status-model.mjs'
import { CONSOLE_PROBE, CONSOLE_VERSION, SKILL_HEAVEN_VERSION } from './meta.ts'
import { agentLabelFor, entryById, qualifyCommand, stageText, summonSuggestion, timeLabel } from './model.ts'
import type { ConsoleAgent, ConsoleEntry, ConsoleSection, ConsoleState } from './model.ts'

/** The elements every surface that draws a band or a pane has in common. */
export type UI = Pick<Elements['desktop'], 'Box' | 'Text' | 'Button'>

export interface BandActions {
  inspect: (id: number) => void
  dismiss: () => void
  /** Pre-fills `/summon <name>` into the prompt. The person submits it. */
  summon: (name: string) => void
}

export interface PaneActions {
  section: (section: ConsoleSection) => void
  toggle: (id: number) => void
  /** Pre-fills a command into the prompt. The person submits it. */
  fill: (text: string) => void
  copy: (text: string) => void
}

/* ------------------------------------------------------------------------- *
 * Colour: roles from the one palette. `ink` is the theme's own text colour,
 * `dim` is the theme's dim; every other role is its palette hex.
 * ------------------------------------------------------------------------- */

type StyleProps = { color?: string; dimColor?: boolean; italic?: boolean; bold?: boolean }

function styleOf(role: Role): StyleProps {
  if (role === 'ink') return {}
  if (role === 'dim') return { dimColor: true }
  return { color: ROLE_COLORS[role].hex }
}

function runs(ui: UI, segments: readonly Segment[], extra: StyleProps = {}): RenderElement {
  const { Text } = ui
  return (
    <Text>
      {segments.map((s) => (
        <Text {...styleOf(s.role)} {...extra}>
          {s.text}
        </Text>
      ))}
    </Text>
  )
}

/* ------------------------------------------------------------------------- *
 * The Lens band — empty by default (the hook returns next(e) for null).
 * ------------------------------------------------------------------------- */

export function renderBand(ui: UI, state: ConsoleState, actions: BandActions, columns: number): RenderElement | null {
  const { Box, Text, Button } = ui
  const band = state.band
  if (band === null) return null
  const width = Math.max(20, columns)

  if (band.kind === 'looking' || band.kind === 'not-connected') {
    const [first, second] = noticeLines(band.kind === 'looking' ? { kind: 'looking', query: band.query } : { kind: 'not-connected' })
    return (
      <Box flexDirection="column" width={width}>
        {first ? runs(ui, first) : null}
        {second ? runs(ui, second) : null}
        <Button key="dismiss" label="Dismiss" role="dismiss" onPress={() => actions.dismiss()} />
      </Box>
    )
  }

  const entry = entryById(state, band.id)
  if (!entry) return null
  const [line1, line2] = eventLines(entry.event)
  const stage = stageText(entry)
  const name = summonSuggestion(entry)
  return (
    <Box flexDirection="column" width={width}>
      {line1 ? runs(ui, line1) : null}
      {line2 ? runs(ui, line2) : null}
      {/* a preview's second line already says "nothing materialized" (seen twice live on 2.1.294) */}
      {entry.event.kind === 'previewed' || (entry.event.kind === 'no-match' && entry.event.preview) ? null : (
        <Text key="stage" dimColor italic={stage.inferred}>
          {'  '}
          {stage.text}
          {stage.inferred ? ' (inferred)' : ''}
        </Text>
      )}
      <Box flexDirection="row" gap={1}>
        {name !== null ? <Button key="summon" label="Summon" variant="primary" onPress={() => actions.summon(name)} /> : null}
        <Button key="inspect" label="Inspect" onPress={() => actions.inspect(entry.id)} />
        <Button key="dismiss" label="Dismiss" role="dismiss" onPress={() => actions.dismiss()} />
      </Box>
    </Box>
  )
}

/* ------------------------------------------------------------------------- *
 * The /heaven pane
 * ------------------------------------------------------------------------- */

const SECTIONS: ReadonlyArray<{ id: ConsoleSection; label: string; hotkey: string }> = [
  { id: 'session', label: 'Session', hotkey: '1' },
  { id: 'scope', label: 'Scope', hotkey: '2' },
  { id: 'flow', label: 'Flow', hotkey: '3' },
  { id: 'trust', label: 'Trust', hotkey: '4' },
]

export function renderPane(ui: UI, state: ConsoleState, actions: PaneActions, columns: number): RenderElement {
  const { Box, Text, Button } = ui
  const width = Math.max(24, columns)
  return (
    <Box flexDirection="column" width={width} gap={1}>
      <Box flexDirection="column">
        <Text>
          <Text bold>Skill Heaven</Text>
          <Text color={ROLE_COLORS.amber.hex}>{'  PREVIEW'}</Text>
          <Text dimColor>{'  console · observes, never changes'}</Text>
        </Text>
        {runs(ui, renderStatusSegments(state.status, 'full'))}
      </Box>
      <Box flexDirection="row" gap={1} flexWrap="wrap">
        {SECTIONS.map((s) => (
          <Button
            key={`section-${s.id}`}
            label={s.label}
            hotkey={s.hotkey}
            variant={state.section === s.id ? 'primary' : 'secondary'}
            onPress={() => actions.section(s.id)}
          />
        ))}
      </Box>
      {state.section === 'session' ? sessionSection(ui, state, actions) : null}
      {state.section === 'scope' ? scopeSection(ui, state, actions) : null}
      {state.section === 'flow' ? flowSection(ui, state) : null}
      {state.section === 'trust' ? trustSection(ui, state) : null}
    </Box>
  )
}

/* -- evidence-labelled rows ------------------------------------------------ */

interface Field {
  name: string
  value: string | null
  evidence: EvidenceClass
}

const FIELD_WIDTH = 16

function fieldRow(ui: UI, f: Field, key: string): RenderElement {
  const { Box, Text } = ui
  const known = f.value !== null && f.value !== '' && f.evidence !== 'unknown'
  const label = f.evidence === 'inferred' ? 'inferred' : f.evidence === 'unknown' || !known ? 'unknown' : f.evidence
  return (
    <Box key={key} flexDirection="row" flexWrap="wrap">
      <Text dimColor>{f.name.padEnd(FIELD_WIDTH)}</Text>
      <Text italic={f.evidence === 'inferred'}>{known ? f.value : '—'}</Text>
      <Text dimColor>{`  ${label}`}</Text>
    </Box>
  )
}

const DIRECTION_WORD: Record<string, string> = {
  manual: 'any (explicit /summon)',
  converge: 'heaven (converge)',
  explore: 'hell (explore)',
  unspecified: 'unspecified',
}

const LANE_WORD: Record<string, string> = {
  'human-led': 'human-led (Skill Heaven lane)',
  'model-led': 'model-led (Skill Hell lane)',
  unspecified: 'unspecified (the source did not classify it)',
}

function healthText(entry: ConsoleEntry): string | null {
  const event = entry.event
  if (!('sourceHealth' in event)) return null
  const h = event.sourceHealth
  if (h.kind === 'unknown') return null
  const age = h.indexAgeDays === null ? '' : ` · index ${h.indexAgeDays} days old`
  return h.kind === 'stale' ? `? stale${age} · ranking still ran` : `fresh${age}`
}

function skillFields(skill: SkillReceipt, index: number, entry: ConsoleEntry): Field[] {
  const stage: Field =
    skill.stage === 'in-context'
      ? { name: 'what entered', value: `body read (in context) by ${entry.readBy[index] ?? 'an agent'}`, evidence: 'observed' }
      : skill.stage === 'materialized'
        ? { name: 'what entered', value: 'card returned · body not read', evidence: 'inferred' }
        : skill.stage === 'previewed'
          ? { name: 'what entered', value: 'previewed · nothing materialized', evidence: 'reported' }
          : { name: 'what entered', value: 'materialized · read not observed', evidence: 'inferred' }
  const rank: string[] = []
  if (skill.matchKind !== 'unknown') rank.push(skill.matchKind)
  const score = formatScore(skill.score)
  if (score) rank.push(score)
  const margin = formatScore(skill.margin)
  if (margin) rank.push(`Δ ${margin} (margin is a retrieval diagnostic)`)
  const from: string[] = []
  if (skill.source) from.push(sanitizeDisplay(skill.source, 48))
  if (skill.repoUrl) from.push(sanitizeDisplay(skill.repoUrl, 64) + (skill.ref ? `@${sanitizeDisplay(skill.ref, 24)}` : ''))
  if (skill.subpath) from.push(sanitizeDisplay(skill.subpath, 48))
  if (skill.sha256) from.push(`sha256 ${sanitizeDisplay(skill.sha256, 12)}…`)
  const cache: string[] = []
  if (skill.cache !== 'unknown') cache.push(skill.cache)
  const ms = formatMs(skill.ms)
  if (ms) cache.push(ms)
  const installability =
    skill.installability === 'unknown' ? null : sanitizeDisplay(skill.installability, 40)
  return [
    stage,
    { name: 'ranking', value: rank.length ? rank.join(' · ') : null, evidence: rank.length ? 'reported' : 'unknown' },
    { name: 'from', value: from.length ? from.join(' · ') : null, evidence: from.length ? 'reported' : 'unknown' },
    {
      name: 'lane',
      value: LANE_WORD[skill.lane] ?? null,
      evidence: LANE_WORD[skill.lane] ? 'reported' : 'unknown',
    },
    {
      name: 'installability',
      value: installability,
      evidence: installability ? 'reported' : 'unknown',
    },
    { name: 'cache', value: cache.length ? cache.join(' · ') : null, evidence: cache.length ? 'reported' : 'unknown' },
    { name: 'on disk', value: skill.path ? sanitizeDisplay(skill.path, 96) : null, evidence: skill.path ? 'reported' : 'unknown' },
  ]
}

function receiptFields(entry: ConsoleEntry, state: ConsoleState): Field[][] {
  const event = entry.event
  const common: Field[] = []
  const query = 'query' in event && event.query ? `query "${sanitizeDisplay(event.query, 80)}" · surface ${DIRECTION_WORD[event.direction] ?? 'unspecified'}` : null
  const health = healthText(entry)
  const agent: Field = {
    name: 'agent',
    value: agentLabelFor(state, entry.agent),
    evidence: 'observed',
  }
  if (event.kind === 'summoned' || event.kind === 'previewed') {
    const groups: Field[][] = []
    common.push({ name: 'why', value: query, evidence: query ? 'reported' : 'unknown' })
    if (event.kind === 'summoned') {
      const comp =
        event.composition === 'relevance-only'
          ? `relevance-only · Arbor: ${event.arbor === 'governed-record' ? 'governed record' : event.arbor === 'no-record' ? 'no governed record' : event.arbor}`
          : null
      common.push({ name: 'composition', value: comp, evidence: comp ? 'reported' : 'unknown' })
    }
    common.push({ name: 'source health', value: health, evidence: health ? 'reported' : 'unknown' }, agent)
    groups.push(common)
    event.skills.slice(0, 3).forEach((skill, i) =>
      groups.push([{ name: 'skill', value: sanitizeDisplay(skill.name, 48), evidence: 'reported' }, ...skillFields(skill, i, entry)]),
    )
    const unshown = event.skills.length - 3 + entry.omitted
    if (unshown > 0) groups.push([{ name: 'more', value: `+${unshown} more not shown here`, evidence: 'observed' }])
    return groups
  }
  if (event.kind === 'no-match') {
    return [
      [
        { name: 'what entered', value: 'nothing materialized', evidence: 'reported' },
        { name: 'why', value: query, evidence: query ? 'reported' : 'unknown' },
        {
          name: 'refusal',
          value:
            (event.considered === null ? '0 admitted' : `${event.considered} considered · 0 admitted`) +
            (event.reason ? ` · ${sanitizeDisplay(event.reason, 60)}` : ''),
          evidence: 'reported',
        },
        { name: 'source health', value: health, evidence: health ? 'reported' : 'unknown' },
        agent,
      ],
    ]
  }
  return [
    [
      { name: 'what entered', value: 'nothing materialized', evidence: 'reported' },
      { name: 'reason', value: sanitizeDisplay(event.reason, 120), evidence: 'observed' },
      agent,
    ],
  ]
}

/* -- Session ----------------------------------------------------------------- */

function sessionSection(ui: UI, state: ConsoleState, actions: PaneActions): RenderElement {
  const { Box, Text, Button } = ui
  const rows = [...state.entries].reverse()
  return (
    <Box flexDirection="column" gap={1}>
      {state.status.summonTool === 'not-connected' ? (
        <Text>
          <Text color={ROLE_COLORS.amber.hex}>{'? '}</Text>
          <Text>{'summon tool: not connected'}</Text>
          <Text dimColor>{`  /summon and /lens cannot reach the Skill Heaven plugin. ${HARNESS_PATHS.find((h) => h.id === 'claude')?.commands[1] ?? ''}`}</Text>
        </Text>
      ) : null}
      {rows.length === 0 ? (
        <Text>
          {'Nothing summoned yet. Try '}
          <Text bold>{`${qualifyCommand('/summon')} <need>`}</Text>
          {' or '}
          <Text bold>{'/lens <need>'}</Text>
          {'.'}
        </Text>
      ) : null}
      {rows.map((entry) => {
        const lines = eventLines(entry.event)
        const open = state.openEntry === entry.id
        const meta = [timeLabel(entry.event.at), agentLabelFor(state, entry.agent), entry.via === 'lens' ? '/lens' : ''].filter(Boolean).join(' · ')
        return (
          <Box key={`entry-${entry.id}`} flexDirection="column">
            {lines[0] ? runs(ui, [...lines[0], { text: meta ? `   ${meta}` : '', role: 'dim' }]) : null}
            {lines[1] ? runs(ui, lines[1]) : null}
            <Button
              key={`toggle-${entry.id}`}
              label={open ? 'Hide receipt' : 'Receipt'}
              plain
              dimColor
              onPress={() => actions.toggle(entry.id)}
            />
            {open
              ? (
                  <Box flexDirection="column" marginLeft={2} gap={1}>
                    {receiptFields(entry, state).map((group, gi) => (
                      <Box key={`group-${gi}`} flexDirection="column">
                        {group.map((f, fi) => fieldRow(ui, f, `f-${gi}-${fi}`))}
                      </Box>
                    ))}
                  </Box>
                )
              : null}
          </Box>
        )
      })}
      <Text dimColor>
        {'Evidence: observed = this console saw it · reported = the summon engine said so · inferred = derived here · unknown = no source.'}
      </Text>
    </Box>
  )
}

/* -- Scope ------------------------------------------------------------------- */

export const ULTRA_COPY =
  'Skill Ultra · provisioned. Controller unavailable — no controller is choosing direction or depth yet. Ultra is the rung you selected; each summon is still judged per use. The long-horizon controller is tracked in #126 and is not yet empirically validated.'

function latestSource(state: ConsoleState): { source: string | null; health: string | null; unavailable: boolean } {
  const last = state.entries[state.entries.length - 1]
  const unavailable = last?.event.kind === 'unavailable'
  for (let i = state.entries.length - 1; i >= 0; i--) {
    const e = state.entries[i]!
    const event = e.event
    if ('skills' in event) {
      const withSource = event.skills.find((s) => s.source)
      if (withSource?.source) return { source: sanitizeDisplay(withSource.source, 56), health: healthText(e), unavailable }
    }
  }
  return { source: null, health: last ? healthText(last) : null, unavailable }
}

function scopeSection(ui: UI, state: ConsoleState, actions: PaneActions): RenderElement {
  const { Box, Text, Button } = ui
  const { source, health, unavailable } = latestSource(state)
  const reading = state.status.reading
  const boot = state.status.boot ?? (reading.kind === 'selected' ? ({ kind: 'native', source: 'no-launcher' } as const) : reading)
  const rung = reading.kind === 'selected' ? reading.rung : null
  const ultra = readingRung(reading) === 'ultra'
  const skills = state.status.skills
  const fields: Field[] = [
    {
      name: 'can see',
      value: unavailable
        ? `skill source ${source ?? ''} · unreachable`.replace('  ', ' ')
        : source
          ? `skill source ${source}${health ? ` · ${health}` : ''}`
          : null,
      evidence: source || unavailable ? 'reported' : 'unknown',
    },
    {
      name: 'active',
      value:
        skills === null
          ? null
          : `${skills} ${skills === 1 ? 'skill' : 'skills'} materialized this session (temporary — gone when the session ends)`,
      evidence: skills === null ? 'unknown' : 'observed',
    },
    {
      name: 'inherited',
      value:
        boot.kind === 'native' || boot.kind === 'unknown'
          ? `boot reading ${readingToken(boot)} — no launcher observed; this console cannot see how the session was started`
          : `boot reading ${readingToken(boot)} — set at launch`,
      evidence: boot.kind === 'native' || boot.kind === 'unknown' ? 'inferred' : 'reported',
    },
    {
      name: 'selected',
      value:
        rung === null
          ? 'none — no rung selected in this session'
          : ultra
            ? 'rung ULTRA · controller unavailable'
            : `rung ${rung.toUpperCase()} — observed from ${state.selectedFrom ?? 'a rung command'} · not enforced`,
      evidence: rung === null ? 'unknown' : 'observed',
    },
    { name: 'allowed', value: '/summon by hand: yes · zero cut: temporary (default)', evidence: 'reported' },
    { name: 'keep small', value: '/skill-zero cuts temporary skills · claude-zero --level zero starts clean', evidence: 'reported' },
  ]
  return (
    <Box flexDirection="column" gap={1}>
      <Box flexDirection="column">{fields.map((f, i) => fieldRow(ui, f, `scope-${i}`))}</Box>
      {rung !== null && !ultra ? (
        <Text dimColor>{`You selected ${rung.toUpperCase()}. Skill Heaven does not enforce a rung; each summon is still judged per use.`}</Text>
      ) : null}
      {ultra ? <Text color={ROLE_COLORS.ultra.hex}>{ULTRA_COPY}</Text> : null}
      <Box flexDirection="column">
        <Text bold>Choose a rung</Text>
        <Text dimColor>These fill your prompt. You press Enter; nothing runs until you do.</Text>
        <Box flexDirection="row" gap={1} flexWrap="wrap">
          <Button key="fill-heaven" label={qualifyCommand('/skill-heaven low')} onPress={() => actions.fill('/skill-heaven low')} />
          <Button key="fill-hell" label={qualifyCommand('/skill-hell high')} onPress={() => actions.fill('/skill-hell high')} />
          <Button key="fill-ultra" label={qualifyCommand('/skill-ultra')} onPress={() => actions.fill('/skill-ultra')} />
        </Box>
        <Text dimColor>{`Other rungs: ${qualifyCommand('/skill-heaven med')} · ${qualifyCommand('/skill-hell xhigh')} · ${qualifyCommand('/skill-hell max')}`}</Text>
      </Box>
      <Box flexDirection="column">
        <Text bold>Keep context small</Text>
        <Box flexDirection="row" gap={1} flexWrap="wrap">
          <Button key="fill-zero" label={qualifyCommand('/skill-zero')} onPress={() => actions.fill('/skill-zero')} />
          <Button key="fill-zero-all" label={qualifyCommand('/skill-zero all')} onPress={() => actions.fill('/skill-zero all')} />
          <Button key="copy-clean" label="Copy: claude-zero --level zero" onPress={() => actions.copy('claude-zero --level zero')} />
        </Box>
        <Text dimColor>Start clean is run in a terminal before a session: it is copied, not run.</Text>
      </Box>
    </Box>
  )
}

/* -- Flow -------------------------------------------------------------------- */

const MAX_AGENT_ROWS = 12

function agentLine(state: ConsoleState, agent: ConsoleAgent): string {
  const mine = state.entries.filter((e) => e.agent !== null && e.agent === agent.id && e.event.kind === 'summoned')
  const skills = mine.reduce((n, e) => n + (e.event.kind === 'summoned' ? e.event.delta : 0), 0)
  const word = agent.state === 'started' ? 'started in background' : agent.state
  return `${word} · ${mine.length === 0 ? 'no skills' : `${mine.length} ${mine.length === 1 ? 'summon' : 'summons'}`}${skills > 0 && skills !== mine.length ? ` (${skills} skills)` : ''}`
}

function flowSection(ui: UI, state: ConsoleState): RenderElement {
  const { Box, Text } = ui
  const mainSummons = state.entries.filter((e) => e.agent === null && e.event.kind === 'summoned')
  const mainInContext = mainSummons.reduce(
    (n, e) => n + (e.event.kind === 'summoned' ? e.event.skills.filter((s) => s.stage === 'in-context').length : 0),
    0,
  )
  const shown = state.agents.slice(0, MAX_AGENT_ROWS)
  const more = state.agents.length - shown.length
  return (
    <Box flexDirection="column" gap={1}>
      <Box flexDirection="column">
        <Text>
          <Text bold>main</Text>
          <Text dimColor>{`   ${mainSummons.length} ${mainSummons.length === 1 ? 'summon' : 'summons'} · ${mainInContext} in context`}</Text>
        </Text>
        {shown.map((agent, i) => {
          const last = i === shown.length - 1 && more <= 0
          return (
            <Text>
              <Text dimColor>{last ? '└─ ' : '├─ '}</Text>
              <Text>{sanitizeDisplay(agent.label, 64)}</Text>
              <Text dimColor>{`   ${agentLine(state, agent)}`}</Text>
            </Text>
          )
        })}
        {more > 0 ? (
          <Text dimColor>{`└─ +${more} more`}</Text>
        ) : null}
      </Box>
      {!state.agentIdsSeen ? (
        <Text dimColor>
          {'This host did not report agent ids. Summons are attributed to main.'}
        </Text>
      ) : null}
      {state.entries.length >= 50 ? <Text dimColor>Counts cover the last 50 events.</Text> : null}
      <Text dimColor>Read-only. Only agents the host reported appear.</Text>
    </Box>
  )
}

/* -- Trust ------------------------------------------------------------------- */

function trustSection(ui: UI, state: ConsoleState): RenderElement {
  const { Box, Text } = ui
  const claude = HARNESS_PATHS.find((h) => h.id === 'claude')!
  const mcp = state.status.summonTool
  const mcpText =
    mcp === 'connected' ? 'connected (a summon result was seen)' : mcp === 'not-connected' ? 'not connected' : 'unknown until the first summon or /lens'
  const row = (name: string, value: string, key: string) => (
    <Box key={key} flexDirection="row" flexWrap="wrap">
      <Text dimColor>{name.padEnd(FIELD_WIDTH)}</Text>
      <Text>{value}</Text>
    </Box>
  )
  return (
    <Box flexDirection="column" gap={1}>
      <Box flexDirection="column">
        {row('skill-heaven', `built for ${SKILL_HEAVEN_VERSION} · gaia-research/gaia-skill-heaven · bundles one MCP server (skill-summon)`, 't1')}
        {row('console (preview)', `${CONSOLE_VERSION} · same repository · runs inside Claude Code as local code`, 't2')}
      </Box>
      <Box flexDirection="column" marginLeft={2}>
        {row('reads', 'summon tool results · your /skill-* commands · Read/Agent tool calls (to observe, never to change)', 't3')}
        {row('writes', 'nothing to disk · session-only $.state', 't4')}
        {row('command text', '/lens and /heaven print a one-line result that the model can read. It is fixed text and carries nothing a skill source supplied.', 't4b')}
        {row('network', "none of its own; /lens calls the bundled summon tool, which fetches the skill source", 't5')}
        {row('disable', '/plugin disable skill-heaven-console — the status entry, band and pane disappear; Skill Heaven is unchanged', 't6')}
      </Box>
      <Box flexDirection="column">
        {row('summon tool', `MCP: ${mcpText}`, 't7')}
        {row(
          'harness',
          `Claude Code ${state.hostVersion ? sanitizeDisplay(state.hostVersion, 24) : '(version not reported)'} · ${CHIP_LABEL[claude.chip]} for the plugin at ${claude.probedVersion ?? 'unknown'}; ${CONSOLE_PROBE}`,
          't8',
        )}
        {row('evidence', claude.evidence, 't9')}
      </Box>
      <Text dimColor>This lists what the code can do. It does not rate it.</Text>
    </Box>
  )
}

